#!/usr/bin/env bash
# ==========================================================================
# Load the CSV data (generated by generate_fake_data.py) into the 5 databases
# of the microservice architecture: user_db, project_db, task_db,
# sprint_db, notification_db on localhost.
#
# Usage:
#   chmod +x load_fake_data.sh
#   ./load_fake_data.sh                       # reads user/password from Backend/.env
#   PGUSER=abc PGPASSWORD=xyz ./load_fake_data.sh   # override when needed
#
# Prerequisites:
#   1. The schema (tables) already exists in each DB (SQL exported from the
#      DBML file, or the services' migrations).
#   2. psql is installed and can connect to localhost.
#   3. The current directory contains the .csv files (users.csv, projects.csv, ...).
#
# IMPORTANT - column names generated by Java/Hibernate may not match the CSV:
#   Each copy_table() call below EXPLICITLY lists the columns in the same
#   order as in the CSV file (as generated). Postgres maps the CSV's i-th
#   column to the i-th column name listed here - it ignores the CSV header
#   and the physical column order in the table.
#   => Before running, compare against `\d <table>` in each DB and FIX the
#      column names to the real ones (e.g. owner_id -> ownerId, is_read -> isRead...)
#      in the corresponding copy_table() line.
#
# NOTE ON TRUNCATE:
#   Before copying, the script runs TRUNCATE ... RESTART IDENTITY CASCADE on
#   each table to wipe the old data (and the data in child tables that
#   reference it via FK). Because of CASCADE the delete order does NOT
#   matter - but it also means: if any table outside the list below has an FK
#   to a truncated table, its data is deleted as well. Make sure you
#   understand the schema before running this against important data.
# ==========================================================================
set -euo pipefail

# Directory containing the CSV files (default = the script's directory).
# On Git Bash/MSYS, `pwd -W` gives C:/... instead of /c/..., which a native Windows psql can open.
DATA_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && { pwd -W 2>/dev/null || pwd; })"

# --------------------------------------------------------------------------
# Connection settings - resolved at runtime, NOT hardcoded in the script.
# Precedence for each value:
#   1. psql's standard environment variables: PGHOST, PGPORT, PGUSER, PGPASSWORD
#   2. POSTGRES_USER / POSTGRES_PASSWORD in Backend/.env (the file
#      docker-compose uses). Use another file with ENV_FILE=/path/to/.env
#   3. Defaults: localhost:5432, user postgres
#   4. If there is still no password -> prompt at runtime (input hidden)
# DB_HOST in .env is "postgres" (a hostname on the docker network), which
# doesn't resolve from the host machine, so it is NOT read from .env - use PGHOST to change it.
# --------------------------------------------------------------------------
ENV_FILE="${ENV_FILE:-$DATA_DIR/../../.env}"

# read_env <KEY> - read the KEY=... value from ENV_FILE, stripping surrounding quotes
read_env() {
  [[ -f "$ENV_FILE" ]] || return 0
  grep -E "^$1=" "$ENV_FILE" | tail -n1 | cut -d= -f2- \
    | sed -e 's/^["'\'']//' -e 's/["'\'']$//' || true
}

DB_HOST="${PGHOST:-localhost}"
DB_PORT="${PGPORT:-5432}"
DB_USER="${PGUSER:-$(read_env POSTGRES_USER)}"
DB_USER="${DB_USER:-postgres}"
PGPASSWORD="${PGPASSWORD:-$(read_env POSTGRES_PASSWORD)}"
if [[ -z "$PGPASSWORD" ]]; then
  read -rsp "Mật khẩu Postgres cho $DB_USER@$DB_HOST:$DB_PORT: " PGPASSWORD
  echo
fi
export PGPASSWORD

echo "Kết nối: $DB_USER@$DB_HOST:$DB_PORT"

# truncate_table <db> <table>
# Wipe the old data before reloading. CASCADE makes Postgres also clear
# tables with an FK referencing this table. RESTART IDENTITY resets
# serial/identity columns (if any) to their initial values.
truncate_table() {
  local db="$1" table="$2"
  echo "  -> TRUNCATE $db.$table"
  psql -h "$DB_HOST" -p "$DB_PORT" -U "$DB_USER" -d "$db" -v ON_ERROR_STOP=1 \
    -c "TRUNCATE TABLE $table RESTART IDENTITY CASCADE"
}

# copy_table <db> <table> <csv> <"col1,col2,col3,...">
# The columns in the 4th argument MUST be in the same order as in the CSV file,
# and MUST be the REAL column names in the Postgres table (not the CSV names).
copy_table() {
  local db="$1" table="$2" csv="$3" columns="$4"
  echo "  -> $db.$table ($columns)  <=  $csv"
  psql -h "$DB_HOST" -p "$DB_PORT" -U "$DB_USER" -d "$db" -v ON_ERROR_STOP=1 \
    -c "\\copy $table ($columns) FROM '$DATA_DIR/$csv' WITH (FORMAT csv, HEADER true)"
}

# load_table <db> <table> <csv> <"col1,col2,...">
# Both steps in one: truncate, then copy.
load_table() {
  local db="$1" table="$2" csv="$3" columns="$4"
  truncate_table "$db" "$table"
  copy_table "$db" "$table" "$csv" "$columns"
}

# --------------------------------------------------------------------------
# 1. user_db
# --------------------------------------------------------------------------
echo "[1/5] Nạp dữ liệu vào user_db..."
load_table user_db users users.csv \
  "id,full_name,email,password,avatar_url,role,created_at,updated_at"

# --------------------------------------------------------------------------
# 2. project_db  (order matters because of FKs within the same DB)
# --------------------------------------------------------------------------
echo "[2/5] Nạp dữ liệu vào project_db..."
load_table project_db projects projects.csv \
  "id,name,description,owner_id,created_at,updated_at"
load_table project_db project_members project_members.csv \
  "id,project_id,user_id,role,joined_at"
load_table project_db project_invitations project_invitations.csv \
  "id,project_id,invitee_id,invited_by_id,status,responded_at,created_at,updated_at"
load_table project_db labels labels.csv \
  "id,project_id,name,color,created_at"

# --------------------------------------------------------------------------
# 3. task_db
# --------------------------------------------------------------------------
echo "[3/5] Nạp dữ liệu vào task_db..."
load_table task_db tasks tasks.csv \
  "id,project_id,title,description,status,priority,assignee_id,reporter_id,parent_task_id,due_date,start_date,created_at,updated_at"
load_table task_db task_comments task_comments.csv \
  "id,task_id,user_id,content,created_at"
load_table task_db task_attachments task_attachments.csv \
  "id,task_id,file_url,file_name,uploaded_by,created_at"
load_table task_db task_labels task_labels.csv \
  "id,task_id,label_id"
load_table task_db task_histories task_histories.csv \
  "id,task_id,changed_by,field,old_value,new_value,created_at"

# --------------------------------------------------------------------------
# 4. sprint_db
# --------------------------------------------------------------------------
echo "[4/5] Nạp dữ liệu vào sprint_db..."
load_table sprint_db sprints sprints.csv \
  "id,project_id,name,status,start_date,end_date,created_at"
load_table sprint_db task_sprints task_sprints.csv \
  "task_id,sprint_id"

# --------------------------------------------------------------------------
# 5. notification_db
# --------------------------------------------------------------------------
echo "[5/5] Nạp dữ liệu vào notification_db..."
load_table notification_db notifications notifications.csv \
  "id,user_id,type,content,entity_id,entity_type,is_read,created_at"

echo ""
echo "Hoàn tất! Đã xóa dữ liệu cũ và nạp dữ liệu mới vào cả 5 database."
